// ---- PEB 系列: SDK 无公开完整定义, 只能手写 ----
//  偏移随目标架构变化。写死一种会在另一种架构上读到*别的字段* ——
//  不报编译错, 也不崩溃, 只是静默读错, 所以更难发现。
//    x64 / ARM64 : PEB.ProcessParameters @ 0x18 ; UPP.CommandLine @ 0x70
//    x86 (32位)  : PEB.ProcessParameters @ 0x10 ; UPP.CommandLine @ 0x3C
//  注: 原实现写的是 0x20 / 0x70 —— 0x20 在 x64 上是 SubSystemData 而非
//      ProcessParameters, 即原 PEB 路径读到的是错的, 本轮一并修正。
#  if defined(_WIN64) || defined(_M_X64) || defined(_M_AMD64) || defined(_M_ARM64)
#    define ZZ_PEB_PROCPARAM_OFF 0x18
#    define ZZ_UPP_CMDLINE_OFF   0x70
#  else
#    define ZZ_PEB_PROCPARAM_OFF 0x10
#    define ZZ_UPP_CMDLINE_OFF   0x3C
#  endif

typedef struct _PEB_STUB {
    unsigned char pad[ZZ_PEB_PROCPARAM_OFF];
    void*         ProcessParameters;
} PEB_STUB;

typedef struct _RTL_USER_PROCESS_PARAMETERS_STUB {
    unsigned char pad[ZZ_UPP_CMDLINE_OFF];
    struct { unsigned short Length; unsigned short MaximumLength; wchar_t* Buffer; } CommandLine;
} RTL_USER_PROCESS_PARAMETERS_STUB;

// UniqueProcessId 在 SDK 中是 ULONG_PTR (x64=8字节 / x86=4字节)。
// 原写死 unsigned long long, 32 位目标上会错位, 故改用 size_t 跟随字长。
typedef struct _PROCESS_BASIC_INFORMATION_STUB {
    void*    Reserved1;
    void*    PebBaseAddress;
    void*    Reserved2[2];
    size_t   UniqueProcessId;
    void*    Reserved3;
} PROCESS_BASIC_INFORMATION_STUB;

#else
