// 内置库查询: 命中即返回家族与来源, 供日志定性
static bool BuiltinIocHit(const std::wstring& hexIn, std::wstring& family, std::wstring& src) {
    if (hexIn.empty()) return false;
    // 自身做大小写归一: 该函数会被多处独立调用, 不能依赖调用方已归一化
    std::wstring h = hexIn;
    for (wchar_t& c : h) if (c >= L'A' && c <= L'Z') c = (wchar_t)(c - L'A' + L'a');
    for (int i = 0; i < g_builtinIocCount; ++i) {
        if (h == g_builtinIocs[i].sha) {
            family = g_builtinIocs[i].family;
            src    = g_builtinIocs[i].src;
            return true;
        }
    }
    return false;
}

