// HKEY 是指针, 不能直接落盘; 持久化时换成编号
static int UndoRootIdx(HKEY r) {
    if (r == HKEY_LOCAL_MACHINE) return 1;
    if (r == HKEY_CURRENT_USER)  return 2;
    if (r == HKEY_CLASSES_ROOT)  return 3;
    if (r == HKEY_USERS)         return 4;
    return 0;
}
static HKEY UndoRootFromIdx(int i) {
    switch (i) {
    case 1: return HKEY_LOCAL_MACHINE;
    case 2: return HKEY_CURRENT_USER;
    case 3: return HKEY_CLASSES_ROOT;
    case 4: return HKEY_USERS;
    }
    return nullptr;
}
