        case IDC_BTN_USB_VACCINE:
            LogPost(L"[U盘免疫] 对所有可移动盘接种(创建只读隐藏的 autorun.inf 目录, 阻止病毒植入自运行配置)");
            LaunchScan([]{ UsbVaccinateAll(); });
