// ===================== 剑盾: 打开方式(文件关联)劫持 =====================
// 病毒改"打开方式"是极常见的持久化: 双击任意 .txt/.exe/.lnk 都先跑它的程序。
// 两处注册表都要看:
//   HKCU\...\Explorer\FileExts\<ext>\UserChoice   <- 用户选的"打开方式"
//   HKCR\<ext> 默认值 -> ProgId -> shell\open\command  <- 系统级关联
// 只查一处会漏: 很多木马只改 UserChoice, HKCR 保持原样。
struct SwordAssocStd { const wchar_t* ext; const wchar_t* progId; };
static const SwordAssocStd kSwordAssocStd[] = {
    { L".exe",  L"exefile"  }, { L".lnk", L"lnkfile" }, { L".bat", L"batfile" },
    { L".cmd",  L"cmdfile"  }, { L".com", L"comfile" }, { L".scr", L"scrfile" },
    { L".txt",  L"txtfile"  }, { L".htm", L"htmlfile"}, { L".html",L"htmlfile"},
    { L".url",  L"InternetShortcut" }, { L".vbs", L"VBSFile" }, { L".js", L"JSFile" },
    { L".ps1",  L"Microsoft.PowerShellScript.1" },
    { L".pdf",  L"AcroExch.Document.DC" },
    { L".jpg",  L"jpgfile"  }, { L".png", L"pngfile" },
    { L".mp4",  L"WMP11.AssocFile.MP4" }, { L".zip", L"CompressedFolder" },
    { L".rar",  L"WinRAR"   }, { L".doc", L"Word.Document.8" },
    { L".docx", L"Word.Document.12" }, { L".xls", L"Excel.Sheet.8" },
    { L".xlsx", L"Excel.Sheet.12" },
};

// ---- 读一个 ProgId 的实际启动命令 ----
static bool SwordAssocCommand(HKEY root, const std::wstring& progId, std::wstring& cmdOut) {
    if (progId.empty()) return false;
    std::wstring sub = progId + L"\\shell\\open\\command";
    HKEY hk = nullptr;
    if (RegOpenKeyExW(root, sub.c_str(), 0, KEY_READ, &hk) != ERROR_SUCCESS || !hk) return false;
    wchar_t buf[4096]; buf[0] = 0; DWORD sz = sizeof(buf), ty = 0;
    bool ok = RegQueryValueExW(hk, nullptr, nullptr, &ty, (LPBYTE)buf, &sz) == ERROR_SUCCESS && buf[0];
    RegCloseKey(hk);
    if (ok) cmdOut = buf;
    return ok;
}

// ---- 从命令串里切出映像路径(去掉引号与参数) ----
static std::wstring SwordAssocImage(const std::wstring& cmdIn) {
    std::wstring s = cmdIn;
    while (!s.empty() && (s[0] == L' ' || s[0] == L'\t')) s.erase(0, 1);
    std::wstring img;
    if (!s.empty() && s[0] == L'"') {
        size_t e = s.find(L'"', 1);
        img = (e == std::wstring::npos) ? s.substr(1) : s.substr(1, e - 1);
    } else {
        // 未加引号: 按空格切; 但 .exe 结尾优先(如 C:\a b\c.exe -x)
        size_t sp = s.find(L' ');
        std::wstring first = (sp == std::wstring::npos) ? s : s.substr(0, sp);
        std::wstring low = ScanLowerW(first);
        if (low.size() >= 4 && low.compare(low.size() - 4, 4, L".exe") == 0) img = first;
        else img = first;
    }
    return img;
}

// ---- 打开方式是否可疑 ----
// 判据从严: 必须"指向可写目录" 或 "指向 LOLBin" 且非微软签名。
// 放宽会把正常软件改关联全部误判(几乎天天发生)。
static bool SwordAssocSuspect(const std::wstring& img, std::wstring& why) {
    if (img.empty()) return false;
    // C:\Windows\Temp / Tasks / debug 等子目录普通用户即可写入, 是恶意程序的经典投放点,
    // 不能仅因父目录是 Windows 就整体豁免(否则劫持到这些目录会漏检)
    {
        const std::wstring lowAll = ScanLowerW(img);
        static const wchar_t* const kHotWin[] = {
            L"\\windows\\temp\\", L"\\windows\\tasks\\", L"\\windows\\debug\\",
            L"\\windows\\tracing\\", L"\\windows\\system32\\tasks\\",
        };
        bool hotWin = false;
        for (const wchar_t* h : kHotWin)
            if (lowAll.find(h) != std::wstring::npos) { hotWin = true; break; }
        if (!hotWin && IsProtectedPath(img)) return false;
    }
    if (SwordIsMsSigned(img)) return false;
    std::wstring low = ScanLowerW(img);
    static const wchar_t* kBins[] = {
        L"\\powershell.exe", L"\\pwsh.exe", L"\\wscript.exe", L"\\cscript.exe",
        L"\\rundll32.exe", L"\\mshta.exe", L"\\cmd.exe", L"\\regsvr32.exe",
        L"\\installutil.exe", L"\\msbuild.exe", L"\\wmic.exe",
    };
    for (const wchar_t* b : kBins) {
        if (low.find(b) != std::wstring::npos) { why = L"指向脚本宿主/LOLBins"; return true; }
    }
    if (HidIsHotDir(low)) { why = L"位于用户可写目录"; return true; }
    return false;
}

static int SwordFileAssocGate() {
    int hit = 0;
    const std::wstring kFileExts =
        L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Explorer\\FileExts\\";
    for (const SwordAssocStd& a : kSwordAssocStd) {
        std::wstring ext = a.ext;
        // (1) UserChoice
        std::wstring ucSub = kFileExts + ext + L"\\UserChoice";
        HKEY hk = nullptr;
        if (RegOpenKeyExW(HKEY_CURRENT_USER, ucSub.c_str(), 0,
                          KEY_READ | KEY_SET_VALUE, &hk) == ERROR_SUCCESS && hk) {
            wchar_t pid[512]; pid[0] = 0; DWORD sz = sizeof(pid), ty = 0;
            if (RegQueryValueExW(hk, L"ProgId", nullptr, &ty, (LPBYTE)pid, &sz) == ERROR_SUCCESS && pid[0]) {
                std::wstring cmd;
                if (SwordAssocCommand(HKEY_CLASSES_ROOT, pid, cmd)) {
                    std::wstring img = SwordAssocImage(cmd);
                    std::wstring why;
                    if (SwordAssocSuspect(img, why)) {
                        LogPost(L"[剑盾] 打开方式被劫持(" + why + L"): " + ext
                                + L" -> " + std::wstring(pid) + L" | " + img);
                        // 清除 UserChoice, 并记录原值以便回滚
                        SwordUndoOp op;
                        op.kind   = SK_UNDO_ASSOC;
                        op.root   = HKEY_CURRENT_USER;
                        op.sub    = ucSub;
                        op.val    = L"ProgId";
                        op.hadOld = true;
                        op.from_  = pid;
                        op.desc   = L"恢复打开方式 " + ext + L" (原 ProgId=" + std::wstring(pid) + L")";
                        if (RegDeleteValueW(hk, L"ProgId") == ERROR_SUCCESS) SwordUndoPush(op);
                        ++hit;
                    }
                }
            }
            RegCloseKey(hk);
        }
        // (2) HKCR\<ext> 默认值被改
        {
            HKEY hc = nullptr;
            if (RegOpenKeyExW(HKEY_CLASSES_ROOT, ext.c_str(), 0,
                              KEY_READ | KEY_SET_VALUE, &hc) == ERROR_SUCCESS && hc) {
                wchar_t defv[512]; defv[0] = 0; DWORD sz = sizeof(defv), ty = 0;
                if (RegQueryValueExW(hc, nullptr, nullptr, &ty, (LPBYTE)defv, &sz) == ERROR_SUCCESS && defv[0]) {
                    std::wstring cmd;
                    if (SwordAssocCommand(HKEY_CLASSES_ROOT, defv, cmd)) {
                        std::wstring img = SwordAssocImage(cmd);
                        std::wstring why;
                        if (SwordAssocSuspect(img, why)) {
                            LogPost(L"[剑盾] 系统关联被劫持(" + why + L"): " + ext
                                    + L" -> " + std::wstring(defv) + L" | " + img);
                            SwordUndoOp op;
                            op.kind   = SK_UNDO_ASSOC;
                            op.root   = HKEY_CLASSES_ROOT;
                            op.sub    = ext;
                            op.val    = L"";
                            op.hadOld = true;
                            op.from_  = defv;
                            op.desc   = L"恢复系统关联 " + ext + L" (原=" + std::wstring(defv) + L")";
                            const std::wstring& std_ = a.progId;
                            if (RegSetValueExW(hc, nullptr, 0, REG_SZ, (const BYTE*)std_.c_str(),
                                    (DWORD)((std_.size() + 1) * sizeof(wchar_t))) == ERROR_SUCCESS)
                                SwordUndoPush(op);
                            ++hit;
                        }
                    }
                }
                RegCloseKey(hc);
            }
        }
    }
    if (hit) LogFmt(L"[剑盾] 打开方式/文件关联: 已恢复 %d 处", hit);
    return hit;
}

// ----------------------------------------------------------------------------
//  v14.33.0.0  打开方式 / 文件关联劫持检测  (只读审计, 不修改任何注册表)
// ----------------------------------------------------------------------------
//  【为什么不复用 SwordFileAssocGate】
//  SwordFileAssocGate 是"门禁": 命中即清除 UserChoice / 改写 HKCR 默认值。
//  它是写操作, 只适合剑盾巡检自动执行; 作为用户手动点击的"检测"按钮不合适
//  ——没人希望点一下"检测"就把自己的文件关联悄悄改掉。
//  因此这里做纯只读版本: 完全复用 SwordAssocCommand / SwordAssocImage /
//  SwordAssocSuspect / kSwordAssocStd, 只报告不修改, 不重复造轮子。
//
//  【为什么要分两级】
//  SwordAssocSuspect 的判据是"指向可写目录 或 指向 LOLBins 且非微软签名",
//  判据从严是为了避免把正常软件改关联全部误判。但攻击者若把恶意程序放进
//  Program Files 并签上名, 第一条就放行了。所以额外给出 DEVIATE 级:
//  仅"实际 ProgId 与系统标准 ProgId 不一致", 不定罪, 交用户判断。
// ----------------------------------------------------------------------------
static void FileAssocAudit(void) {
    LogPost(L"===== 打开方式 / 文件关联劫持检测 (只读, 不修改注册表) =====");
    const std::wstring kFileExts =
        L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Explorer\\FileExts\\";
    int suspect = 0, deviate = 0, checked = 0;
    for (const SwordAssocStd& a : kSwordAssocStd) {
        const std::wstring ext = a.ext;
        const std::wstring stdProg = a.progId;
        ++checked;
        // (1) 用户选择的打开方式: HKCU\...\FileExts\<ext>\UserChoice
        {
            HKEY hk = nullptr;
            if (RegOpenKeyExW(HKEY_CURRENT_USER, (kFileExts + ext + L"\\UserChoice").c_str(),
                              0, KEY_READ, &hk) == ERROR_SUCCESS && hk) {
                wchar_t pid[512]; pid[0] = 0; DWORD sz = sizeof(pid), ty = 0;
                if (RegQueryValueExW(hk, L"ProgId", nullptr, &ty,
                                     (LPBYTE)pid, &sz) == ERROR_SUCCESS && pid[0]) {
                    std::wstring cmd;
                    if (SwordAssocCommand(HKEY_CLASSES_ROOT, pid, cmd)) {
                        std::wstring img = SwordAssocImage(cmd);
                        std::wstring why;
                        if (SwordAssocSuspect(img, why)) {
                            ++suspect;
                            LogPost(L"  [高危] UserChoice 被劫持(" + why + L"): "
                                    + ext + L" -> " + std::wstring(pid));
                            LogPost(L"         实际执行: " + img);
                            SetThreatLevel(THREAT_DANGER,
                                (std::wstring(L"打开方式被劫持: ") + ext + L" -> " + img).c_str());
                        } else if (_wcsicmp(pid, stdProg.c_str()) != 0) {
                            ++deviate;
                            LogPost(L"  [提示] UserChoice 偏离系统标准: " + ext
                                    + L" -> " + std::wstring(pid)
                                    + L" (标准=" + stdProg + L", 可能为用户主动更改)");
                            LogPost(L"         实际执行: " + img);
                        }
                    }
                }
                RegCloseKey(hk);
            }
        }
        // (2) 系统级关联: HKCR\<ext> 默认值 -> ProgId -> shell\open\command
        {
            HKEY hc = nullptr;
            if (RegOpenKeyExW(HKEY_CLASSES_ROOT, ext.c_str(), 0,
                              KEY_READ, &hc) == ERROR_SUCCESS && hc) {
                wchar_t defv[512]; defv[0] = 0; DWORD sz = sizeof(defv), ty = 0;
                if (RegQueryValueExW(hc, nullptr, nullptr, &ty,
                                     (LPBYTE)defv, &sz) == ERROR_SUCCESS && defv[0]) {
                    std::wstring cmd;
                    if (SwordAssocCommand(HKEY_CLASSES_ROOT, defv, cmd)) {
                        std::wstring img = SwordAssocImage(cmd);
                        std::wstring why;
                        if (SwordAssocSuspect(img, why)) {
                            ++suspect;
                            LogPost(L"  [高危] 系统关联被劫持(" + why + L"): "
                                    + ext + L" -> " + std::wstring(defv));
                            LogPost(L"         实际执行: " + img);
                            SetThreatLevel(THREAT_DANGER,
                                (std::wstring(L"文件关联被劫持: ") + ext + L" -> " + img).c_str());
                        } else if (_wcsicmp(defv, stdProg.c_str()) != 0) {
                            ++deviate;
                            LogPost(L"  [提示] 系统关联偏离标准: " + ext
                                    + L" -> " + std::wstring(defv)
                                    + L" (标准=" + stdProg + L")");
                            LogPost(L"         实际执行: " + img);
                        }
                    }
                }
                RegCloseKey(hc);
            }
        }
    }
    LogFmt(L"打开方式检测完成: 检查 %d 个扩展名, 高危劫持 %d 处, 偏离标准 %d 处",
           checked, suspect, deviate);
    if (suspect) {
        LogPost(L"  高危项说明: 关联指向可写目录或脚本宿主(LOLBins)且非微软签名, "
                L"是典型的打开方式劫持。可开启剑盾模式自动清除, 或用 assoc/ftype 手动修复。");
    } else {
        LogPost(L"  未发现高危的打开方式劫持");
    }
    if (deviate) LogPost(L"  注意: 「偏离标准」不定罪——正常软件(如 WPS/记事本替代/播放器)改关联也会命中, 请自行判断");
}

// ---- 命令行门禁: 逐条比对 ----
static int SwordCmdRuleGate() {
    auto procs = SnapshotProcs();
    int hit = 0;
    DWORD self = GetCurrentProcessId();
    for (auto& p : procs) {
        if (!p.pid || p.pid == 4 || p.pid == self) continue;
        std::wstring path = GetProcPath(p.pid);
        if (!path.empty() && (ProcIsCriticalByPath(path) || IsProtectedPath(path))) continue;
        std::wstring cl = GetProcCommandLine(p.pid);
        if (cl.empty()) continue;
        std::wstring lcl = ScanLowerW(cl);
        for (auto& r : kSwordCmdRules) {
            std::wstring kw = ScanLowerW(r.kw);
            if (lcl.find(kw) == std::wstring::npos) continue;
            // 系统目录下的系统程序执行这些命令属正常(如系统自己的关机流程)
            if (SwordIsMsSigned(path)) break;
            LogPost(L"[剑盾] 命中规则「" + std::wstring(r.desc) + L"」: "
                    + p.name + L" PID=" + std::to_wstring(p.pid));
            ShieldKillNow(p.pid, std::wstring(r.desc));
            ++hit;
            break;
        }
    }
    return hit;
}

// ---- 复制到临时文件夹(单独处理, 需同时含临时目录才判定) ----
static int SwordTempCopyGate() {
    auto procs = SnapshotProcs();
    int hit = 0;
    DWORD self = GetCurrentProcessId();
    for (auto& p : procs) {
        if (!p.pid || p.pid == 4 || p.pid == self) continue;
        std::wstring path = GetProcPath(p.pid);
        if (!path.empty() && (ProcIsCriticalByPath(path) || IsProtectedPath(path))) continue;
        if (!path.empty() && SwordIsMsSigned(path)) continue;
        std::wstring cl = ScanLowerW(GetProcCommandLine(p.pid));
        if (cl.empty()) continue;
        bool isCopy = cl.find(L"copy ") != std::wstring::npos ||
                      cl.find(L"xcopy") != std::wstring::npos ||
                      cl.find(L"robocopy") != std::wstring::npos ||
                      cl.find(L"copy-item") != std::wstring::npos;
        if (!isCopy) continue;
        bool toTemp = cl.find(L"\\temp") != std::wstring::npos ||
                      cl.find(L"%temp%") != std::wstring::npos ||
                      cl.find(L"\\appdata\\local\\temp") != std::wstring::npos ||
                      cl.find(L"\\windows\\temp") != std::wstring::npos;
        if (!toTemp) continue;
        LogPost(L"[剑盾] 命中规则「不允许复制文件到临时文件夹」: "
                + p.name + L" PID=" + std::to_wstring(p.pid));
        ShieldKillNow(p.pid, L"不允许复制文件到临时文件夹");
        ++hit;
    }
    return hit;
}

// ---- 改后缀名(单独处理) ----
static int SwordRenameExtGate() {
    auto procs = SnapshotProcs();
    int hit = 0;
    DWORD self = GetCurrentProcessId();
    for (auto& p : procs) {
        if (!p.pid || p.pid == 4 || p.pid == self) continue;
        std::wstring path = GetProcPath(p.pid);
        if (!path.empty() && (ProcIsCriticalByPath(path) || IsProtectedPath(path))) continue;
        if (!path.empty() && SwordIsMsSigned(path)) continue;
        std::wstring cl = ScanLowerW(GetProcCommandLine(p.pid));
        if (cl.empty()) continue;
        bool isRen = cl.find(L"ren ") != std::wstring::npos ||
                     cl.find(L"rename") != std::wstring::npos ||
                     cl.find(L"move ") != std::wstring::npos ||
                     cl.find(L"rename-item") != std::wstring::npos;
        if (!isRen) continue;
        // 只关心可执行文件后缀的改动
        bool extHit = cl.find(L".exe") != std::wstring::npos ||
                      cl.find(L".dll") != std::wstring::npos ||
                      cl.find(L".scr") != std::wstring::npos ||
                      cl.find(L".bat") != std::wstring::npos ||
                      cl.find(L".cmd") != std::wstring::npos;
        if (!extHit) continue;
        LogPost(L"[剑盾] 命中规则「不允许修改后缀名」: "
                + p.name + L" PID=" + std::to_wstring(p.pid));
        ShieldKillNow(p.pid, L"不允许修改后缀名");
        ++hit;
    }
    return hit;
}

// ---- 开机自启写入(Run 键) ----
static int SwordAutorunGate() {
    auto procs = SnapshotProcs();
    int hit = 0;
    DWORD self = GetCurrentProcessId();
    for (auto& p : procs) {
        if (!p.pid || p.pid == 4 || p.pid == self) continue;
        std::wstring path = GetProcPath(p.pid);
        if (!path.empty() && (ProcIsCriticalByPath(path) || IsProtectedPath(path))) continue;
        if (!path.empty() && SwordIsMsSigned(path)) continue;
        std::wstring cl = ScanLowerW(GetProcCommandLine(p.pid));
        if (cl.empty()) continue;
        bool writesRun = (cl.find(L"reg add") != std::wstring::npos ||
                          cl.find(L"new-itemproperty") != std::wstring::npos ||
                          cl.find(L"set-itemproperty") != std::wstring::npos) &&
                         (cl.find(L"\\run") != std::wstring::npos ||
                          cl.find(L"\\runonce") != std::wstring::npos ||
                          cl.find(L"startup") != std::wstring::npos);
        if (!writesRun) continue;
        LogPost(L"[剑盾] 命中规则「不允许开机自启」: "
                + p.name + L" PID=" + std::to_wstring(p.pid));
        ShieldKillNow(p.pid, L"不允许开机自启");
        ++hit;
    }
    return hit;
}

// ---- 未签名应用禁止运行 ----
static int SwordUnsignedGate() {
    auto procs = SnapshotProcs();
    int hit = 0;
    DWORD self = GetCurrentProcessId();
    for (auto& p : procs) {
        if (!p.pid || p.pid == 4 || p.pid == self) continue;
        std::wstring path = GetProcPath(p.pid);
        if (path.empty()) continue;
        if (ProcIsCriticalByPath(path) || IsProtectedPath(path)) continue;
        // v14.15: 原为 VerifyFileSignature(path)==1 -> continue,
        // 但它用 WTD_REVOKE_NONE(不查吊销), 任何"有效签名"(含廉价购买/窃取/
        // 自签+导入根/已吊销)都会被放行。改复用 SignAllowsRelease(整链吊销
        // 检查 + 自签名 + 伪造微软身份 + 身份与位置矛盾)。
        // v14.16: 但"买来的合法证书"签名链同样有效、根也是真实商业根、不在吊销
        // 列表 —— SignAllowsRelease 依然会放行。签名只证明"谁签的", 证明不了
        // "是否恶意", 这是签名机制的固有边界, 任何只看签名的方案都堵不上。
        // 剑盾是极端模式, 改用发布者信誉: 微软根或本机已确认的发布者才放行,
        // 【首次出现的发布者一律不放行】(恶意软件首次运行必然命中这一条)。
        std::wstring sigWhy;
        if (g_cfg.swordStrictSign) {
            SignInfoW psi = SignVerifyDeep(path);
            std::wstring pwhy;
            int trust = SignPublisherTrust(path, psi, pwhy);
            if (trust >= 2) continue;
            LogPost(L"[剑盾] 严格签名模式不放行: " + pwhy + L" | " + p.name + L" | " + path);
            ShieldKillNow(p.pid, L"未通过发布者信誉(首次出现/不可信)");
            ++hit;
            continue;
        }
        if (SignAllowsRelease(path, sigWhy)) continue;
        LogPost(L"[剑盾] 未签名应用禁止运行: " + p.name + L" | " + path);
        ShieldKillNow(p.pid, L"未签名应用禁止运行");
        ++hit;
    }
    return hit;
}

// ---- 所有网络连接均阻止(剑盾: 不询问, 直接阻断) ----
static int SwordNetBlockAll() {
    EnumTcpConnections();
    auto nets = SnapshotNets();
    auto procs = SnapshotProcs();
    int blocked = 0;
    for (auto& n : nets) {
        std::wstring ip = ExtractIpFromRemote(n.remote);
        if (ip.empty()) continue;
        if (!IntelIsExternalIp(ip)) continue;           // 内网不打扰
        std::wstring path = GetProcPath(n.pid);
        if (!path.empty() && ProcIsCriticalByPath(path)) continue;
        std::wstring pname;
        for (auto& p : procs) if (p.pid == n.pid) pname = p.name;
        LogPost(L"[剑盾] 阻止网络连接: " + pname + L" -> " + n.remote);
        ShieldBlockIp(ip);
        ++blocked;
    }
    if (blocked) LogFmt(L"[剑盾] 网络阻断: %d 条", blocked);
    return blocked;
}

// ---- 境外 IP: 不允许连接 ----
static int SwordForeignIpGate() {
    EnumTcpConnections();
    auto nets = SnapshotNets();
    int hit = 0;
    for (auto& n : nets) {
        std::wstring ip = ExtractIpFromRemote(n.remote);
        if (ip.empty()) continue;
        if (!IntelIsForeignIp(ip)) continue;            // 境外判定
        std::wstring path = GetProcPath(n.pid);
        if (!path.empty() && ProcIsCriticalByPath(path)) continue;
        LogPost(L"[剑盾] 不允许连接境外IP: " + n.remote);
        ShieldBlockIp(ip);
        ++hit;
    }
    if (hit) LogFmt(L"[剑盾] 境外IP阻断: %d 条", hit);
    return hit;
}

// ---- 禁止访问剪贴板 ----
static int SwordClipGate() {
    // 清空剪贴板并阻断后续读取: 用户态做法是持续清空,
    // 使得任何应用在剑盾模式下都读不到内容。
    if (OpenClipboard(nullptr)) {
        EmptyClipboard();
        CloseClipboard();
    }
    auto procs = SnapshotProcs();
    int hit = 0;
    DWORD self = GetCurrentProcessId();
    for (auto& p : procs) {
        if (!p.pid || p.pid == 4 || p.pid == self) continue;
        std::wstring path = GetProcPath(p.pid);
        if (!path.empty() && (ProcIsCriticalByPath(path) || IsProtectedPath(path))) continue;
        std::wstring cl = ScanLowerW(GetProcCommandLine(p.pid));
        if (cl.empty()) continue;
        bool clip = cl.find(L"get-clipboard") != std::wstring::npos ||
                    cl.find(L"set-clipboard") != std::wstring::npos ||
                    cl.find(L"getclipboard") != std::wstring::npos ||
                    cl.find(L"clip.exe") != std::wstring::npos;
        if (!clip) continue;
        LogPost(L"[剑盾] 禁止访问剪贴板: " + p.name + L" PID=" + std::to_wstring(p.pid));
        ShieldKillNow(p.pid, L"禁止访问剪贴板");
        ++hit;
    }
    return hit;
}

// ---- 隐藏文件夹: 禁止创建与读取 ----
static int SwordHiddenItemGate() {
    const wchar_t* dirs[] = {
        L"%USERPROFILE%\\Desktop", L"%USERPROFILE%\\Downloads", L"%USERPROFILE%\\Documents"
    };
    int hit = 0;
    wchar_t prof[MAX_PATH]; prof[0] = 0;
    ExpandEnvironmentStringsW(L"%USERPROFILE%", prof, MAX_PATH);
    std::wstring base(prof);
    const wchar_t* subs[] = { L"\\Desktop", L"\\Downloads", L"\\Documents" };
    for (const wchar_t* s : subs) {
        std::wstring dir = base + s;
        std::wstring find = dir + L"\\*";
        WIN32_FIND_DATAW fd;
        HANDLE h = FindFirstFileW(find.c_str(), &fd);
        if (h == INVALID_HANDLE_VALUE) continue;
        do {
            if (!(fd.dwFileAttributes & FILE_ATTRIBUTE_HIDDEN)) continue;
            std::wstring full = dir + L"\\" + fd.cFileName;
            DWORD a = GetFileAttributesW(full.c_str());
            if (a != INVALID_FILE_ATTRIBUTES) {
                SetFileAttributesW(full.c_str(), a & ~FILE_ATTRIBUTE_HIDDEN);
                LogPost(L"[剑盾] 已取消隐藏(剑盾下不允许隐藏项): " + full);
                ++hit;
            }
        } while (FindNextFileW(h, &fd));
        FindClose(h);
    }
    (void)dirs;
    return hit;
}

// ---- 禁止弹窗 + 禁止后台运行 ----
// 【为什么合并】"不允许弹出窗口"与"禁止后台运行"是同一个判据的两面:
// 剑盾下只允许"系统签名的正常程序"存在, 来自可写目录且未签名的进程,
// 无论有无窗口都终止。已签名的正规软件(在 Program Files)不受影响,
// 所以不会把用户正常安装的软件杀掉。
static int SwordPopupBgGate() {
    auto procs = SnapshotProcs();
    int hit = 0;
    DWORD self = GetCurrentProcessId();
    for (auto& p : procs) {
        if (!p.pid || p.pid == 4 || p.pid == self) continue;
        std::wstring path = GetProcPath(p.pid);
        if (path.empty()) continue;
        if (ProcIsCriticalByPath(path) || IsProtectedPath(path)) continue;
        if (SwordIsMsSigned(path)) continue;            // 正规签名软件放行
        bool visible = ShieldHasVisibleWindow(p.pid);
        const wchar_t* why = visible ? L"禁止应用弹出窗口" : L"禁止应用后台运行";
        LogPost(L"[剑盾] " + std::wstring(why) + L": " + p.name + L" | " + path);
        ShieldKillNow(p.pid, why);
        ++hit;
    }
    return hit;
}

// ---- 敏感权限锁死: 摄像头 / 麦克风 / 定位 ----
// 摄像头与麦克风: 交由既有的虚拟化模块, 模式 0 = 全黑画面 / 绝对静音。
// 定位: 关闭定位开关并把坐标固定在 0,0 (Null Island)。
// 【如实说明】真正的"喂给应用一帧全黑画面"需要驱动级过滤;
// 用户态这里的做法是关闭设备访问权限, 使应用拿不到画面与声音。
static void SwordPrivLock() {
    if (!g_cfg.camOn)     { g_cfg.camOn = true;     LogPost(L"[剑盾] 摄像头访问已阻断(全黑)"); }
    if (!g_cfg.micOn)     { g_cfg.micOn = true;     LogPost(L"[剑盾] 麦克风访问已阻断(静音)"); }
    if (g_cfg.camMode != 0) { g_cfg.camMode = 0;    LogPost(L"[剑盾] 摄像头模式=0(全黑画面)"); }
    if (g_cfg.micMode != 0) { g_cfg.micMode = 0;    LogPost(L"[剑盾] 麦克风模式=0(绝对安静)"); }

    // 定位: 关闭系统定位开关
    SwordSetDword(HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Policies\\Microsoft\\Windows\\LocationAndSensors",
        L"DisableLocation", 1);
    SwordSetDword(HKEY_CURRENT_USER,
        L"Software\\Microsoft\\Windows\\CurrentVersion\\CapabilityAccessManager\\ConsentStore\\location",
        L"Value", 0);
    // 坐标固定为 0,0 N; 0,0 W (Null Island)
    SwordSetDword(HKEY_CURRENT_USER,
        L"Software\\Microsoft\\Windows\\CurrentVersion\\Location\\Training",
        L"ZZSwordLatX1000", 0);
    SwordSetDword(HKEY_CURRENT_USER,
        L"Software\\Microsoft\\Windows\\CurrentVersion\\Location\\Training",
        L"ZZSwordLonX1000", 0);
}

// ---- 强制系统策略(可真正写注册表生效的部分) ----
static void SwordApplyPolicy() {
    // 不允许关闭 Windows 防病毒
    SwordSetDword(HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Policies\\Microsoft\\Windows Defender",
        L"DisableAntiSpyware", 0);
    SwordSetDword(HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Policies\\Microsoft\\Windows Defender\\Real-Time Protection",
        L"DisableRealtimeMonitoring", 0);
    SwordSetDword(HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Policies\\Microsoft\\Windows Defender\\Real-Time Protection",
        L"DisableBehaviorMonitoring", 0);
    // 不允许暂停更新
    SwordSetDword(HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Policies\\Microsoft\\Windows\\WindowsUpdate\\AU",
        L"NoAutoUpdate", 0);
    SwordSetDword(HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Policies\\Microsoft\\Windows\\WindowsUpdate\\AU",
        L"AUOptions", 2);
    // 禁止无登录关机(降低被应用关机的面)
    SwordSetDword(HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System",
        L"ShutdownWithoutLogon", 0);
    // 不允许安装证书(禁止根证书自动更新)
    SwordSetDword(HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Policies\\Microsoft\\SystemCertificates\\AuthRoot",
        L"DisableRootAutoUpdate", 1);
    // 不允许删除系统还原点(开启系统保护)
    SwordSetDword(HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\SystemRestore",
        L"DisableSR", 0);
    // 不允许侧加载
    SwordSetDword(HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Policies\\Microsoft\\Windows\\Appx",
        L"AllowDevelopmentWithoutDevLicense", 0);
    LogPost(L"[剑盾] 已强制写入系统策略(Defender/更新/关机/证书/还原点/侧加载)");
}

// ---- 剑盾主循环 ----
static void SwordTick() {
    if (!g_cfg.swordGuardOn) return;
    SwordPrivLock();
    SwordApplyPolicy();
    // v14.11: 各 Gate 返回命中数, 累加后在轮末统一触发 SwordTrigger 完整处置链
    int hits = 0;
    hits += SwordCmdRuleGate();
    hits += SwordTempCopyGate();
    hits += SwordRenameExtGate();
    hits += SwordAutorunGate();
    hits += SwordUnsignedGate();
    hits += SwordNetBlockAll();
    hits += SwordForeignIpGate();
    hits += SwordClipGate();
    hits += SwordHiddenItemGate();
    hits += SwordPopupBgGate();
    hits += SwordFileAssocGate();
    if (hits <= 0) return;
    // 节流: 完整处置链会结束所有非系统进程, 不能每 3 秒执行一次
    unsigned long long now = GetTickCount64();
    if (g_swordLastChainMs != 0 && now - g_swordLastChainMs < kSwordChainGapMs) return;
    if (!g_swordLastPid && g_swordLastPath.empty()) return;   // 无明确目标则不盲打
    g_swordLastChainMs = now;
    SwordTrigger(g_swordLastReason.empty() ? L"剑盾规则命中" : g_swordLastReason,
                 g_swordLastPid, g_swordLastPath);
}

// ---- 开启/关闭 ----
// ---------------------------------------------------------------------------
//  v14.18  剑盾免责声明 + 静默启用
// ---------------------------------------------------------------------------
//  【用户明确要求】剑盾下"直接处理不通知", 但开启前必须有一次弹窗:
//   (a) 说清剑盾会做什么;
//   (b) 免责声明 —— 出现任何问题概不负责;
//   (c) 企业/IT 管控的机器, 建议第一时间联系 IT 支持, 而不是自行清除策略;
//   (d) 用户选择「仍要开启」后, 立即启用并第一时间禁用限制策略。
//
//  【为什么免责这一条不能省】剑盾会结束所有非系统进程、改写系统策略、阻断
//  全部外连。在企业受管机器上, 这些动作可能与公司合规要求冲突, 甚至违反
//  管理规定。把风险前置告知, 是这类破坏性功能唯一的自我保护; 用户知情后
//  自行承担, 也是所有安全工具的通行做法。
//
//  【域判定复用 v14.18 已有实现】GpoDomainVerdict 的前向声明已在文件前段给出,
//  此处直接复用, 不重复造轮子。
// ---------------------------------------------------------------------------
static void SwordDisclaimerText(std::wstring& out) {
    out.clear();
    out += L"剑盾守护模式(最高等级)启用后将执行:\r\n\r\n";
    out += L"· 未签名应用禁止运行(严格签名: 仅微软根或本机已确认发布者)\r\n";
    out += L"· 所有外部网络连接直接阻断; 境外 IP 一律阻断\r\n";
    out += L"· 禁止隐藏运行命令、禁止隐藏文件与目录\r\n";
    out += L"· 摄像头全黑 / 麦克风静音 / 定位关闭(坐标 0,0)\r\n";
    out += L"· 禁止访问剪贴板、禁止创建日程、禁止应用弹窗与后台运行\r\n";
    out += L"· 不允许改时间、暂停更新、关 Defender、删还原点\r\n";
    out += L"· 不允许装证书、开机自启、侧加载、改后缀名、复制文件到临时目录\r\n";
    out += L"· 触发任意规则即: 内存转储 → 隔离改后缀 → 全盘扫描 → 结束所有非系统进程\r\n";
    out += L"\r\n【静默处理(本次新增)】\r\n";
    out += L"· 开启后所有处置【不再询问、不再弹窗】, 直接执行\r\n";
    out += L"· 结论只写入日志页, 你需要主动查看才知道发生过什么\r\n";
    out += L"· 期间不会有任何提示打断你, 也不会等你确认\r\n";

    // ---- 企业/IT 管控判定: 这一段决定「该不该自行清除策略」 ----
    std::wstring dom, how;
    bool joined = GpoIsDomainJoined(dom, how);
    bool hist   = GpoHasRealHistory();
    std::wstring verdict;
    int bump = 0;
    GpoDomainVerdict(joined, dom, hist, verdict, bump);
    LogPost(L"[剑盾·免责] 域成员=" + std::wstring(joined ? (L"是(" + dom + L")") : L"否")
            + L"  真实GPO下发记录=" + (hist ? L"有" : L"无"));

    out += L"\r\n【企业/IT 管控提示】\r\n";
    if (joined) {
        out += L"⚠️ 本机已加入域「" + dom + L"」, 属于【企业受管机器】。\r\n";
        out += L"剑盾会禁用/清除组策略限制、改写 Defender 与更新策略, 这些动作\r\n";
        out += L"很可能与公司 IT 管理规定冲突, 也可能触发合规审计告警。\r\n";
        out += L"\r\n强烈建议: 【第一时间联系公司 IT 支持或安全团队】, 由他们在\r\n";
        out += L"域控侧处置。自行清除域策略, 后果由你本人承担。\r\n";
    } else {
        out += L"本机未加入域(工作组/单机)。\r\n";
        out += L"若这台机器实际属于公司资产, 仍建议先联系 IT 支持确认;\r\n";
        out += L"若确为个人机器, 可继续。\r\n";
    }
    if (!joined && hist) {
        out += L"\r\n注: 检测到本机存在 GPO 下发记录但未加入域, 可能曾脱离域或\r\n";
        out += L"策略残留, 清除前请确认无合规要求。\r\n";
    }

    out += L"\r\n【免责声明】\r\n";
    out += L"本功能为高风险应急手段, 可能导致:\r\n";
    out += L"· 正在运行的程序(浏览器/编辑器/业务软件)被强制结束, 未保存数据丢失\r\n";
    out += L"· 网络中断、业务系统掉线、共享与打印不可用\r\n";
    out += L"· 系统策略被改写, 与企业管控要求冲突\r\n";
    out += L"· 极端情况下系统不稳定, 需要修复或重装\r\n";
    out += L"\r\n选择「仍要开启」即表示你已充分知悉上述风险, 并自愿承担全部后果。\r\n";
    out += L"因使用本功能造成的任何损失(含数据丢失、业务中断、合规责任),\r\n";
    out += L"本软件及作者概不负责。\r\n";
    out += L"\r\n企业受管机器请务必先寻求 IT 支持与帮助。\r\n";
    out += L"\r\n是否仍要开启剑盾守护?";
}

// 弹免责声明并取用户确认。返回 true = 选择「仍要开启」。
// 同一进程内只弹一次: `emergency shield` 会同时命中 sword 与 emergency
// 两个分支, 不记状态就会连弹两次同样的声明。
static bool g_swordDisclaimerShown = false;
static bool SwordDisclaimerConfirm(HWND h) {
    if (g_swordDisclaimerShown) return true;
    std::wstring text;
    SwordDisclaimerText(text);
    int r = MessageBoxW(h, text.c_str(), L"剑盾守护模式 - 免责声明",
                        MB_YESNO | MB_ICONWARNING | MB_DEFBUTTON2 | MB_TOPMOST);
    g_swordDisclaimerShown = (r == IDYES);
    if (r != IDYES)
        LogPost(L"[剑盾] 用户未确认免责声明, 取消开启(已建议联系 IT 支持)");
    else
        LogPost(L"[剑盾] 用户已确认免责声明, 选择仍要开启");
    return g_swordDisclaimerShown;
}

// 静默启用: 不弹任何提示, 直接生效并立即禁用限制策略
static void SwordEnableNow(HWND h) {
    g_cfg.swordGuardOn   = true;
    g_cfg.swordSilent    = true;
    g_cfg.swordDisclaimer = true;
    g_cfg.alertAskOn     = false;          // 剑盾静默: 不再逐项询问
    g_alertAsk.store(false);
    g_swordSilent.store(true);
    ShieldApplyStrict();                   // 开启此前全部检测项

    // ---- 第一时间禁用限制策略(用户要求: 选择仍要开启后立即执行) ----
    // 顺序有讲究: 先移走策略源文件 Registry.pol, 再改 Policies 结果键。
    // 反过来的话, 任何一次 gpupdate 都会把刚改好的值刷回去, 等于白改。
    int pol = GpoPolicyPolClear();
    LogFmt(L"[剑盾] 已移走组策略源文件(Registry.pol): %d 处", pol);
    SwordApplyPolicy();                    // Defender/更新/关机/证书/还原点/侧加载
    SwordPrivLock();                       // 摄像头/麦克风/定位

    LogPost(L"[剑盾] ===== 剑盾守护模式已开启(静默) =====");
    LogPost(L"[剑盾] 处置将不询问、不弹窗, 结论仅写入日志");
    SysNotify(L"剑盾守护已开启", L"已进入静默处置模式, 详情见日志");
    g_cfg.Save(CfgDefaultPath().c_str());
    // 开启后主动弹出数据看板: 用户要求"开启之后主动弹出"
    PostMessageW(g_hMain ? g_hMain : h, WM_APP_DASHOPEN, 0, 0);
}

static void SwordGuardToggle(HWND h) {
    if (!g_cfg.swordGuardOn) {
        if (!SwordDisclaimerConfirm(h)) return;
        SwordEnableNow(h);
    } else {
        g_cfg.swordGuardOn = false;
        g_swordSilent.store(false);
        g_alertAsk.store(g_cfg.alertAskOn);
        if (g_cfg.alertAskOn) g_alertAsk.store(true);
        LogPost(L"[剑盾] ===== 剑盾守护模式已关闭 =====");
        g_cfg.Save(CfgDefaultPath().c_str());
    }
}

// ---- 供主循环调用 ----
// 【修复】此前本函数与 ShieldGuardRunOnce 定义后从未被调用: 剑盾开关
// 只改了配置, 守护逻辑一行都没跑过(死代码)。现由下方独立守护线程驱动。
static void SwordGuardRunOnce() {
    if (!g_cfg.swordGuardOn) return;
    if (g_swordRunning) return;       // 防止重入
    g_swordRunning = true;
    SwordTick();
    g_swordRunning = false;
}

// ---- 剑盾守护线程: 自动周期触发(不依赖用户点按钮) ----
// 与 ResourceGuardLoop 同构: 长驻、可被 g_running 终止、不占 UI 线程。
static void SwordGuardLoop() {
    while (g_running.load()) {
        for (int i = 0; i < 3 && g_running.load(); ++i) Sleep(1000);
        if (!g_running.load()) break;
        if (!g_cfg.swordGuardOn) continue;
        SwordGuardRunOnce();
    }
}

static int EnsureSelfRunnable() {
    int fixed = 0;
    wchar_t self[MAX_PATH]; self[0] = 0;
    GetModuleFileNameW(nullptr, self, MAX_PATH);
    std::wstring selfS(self);
    size_t bs = selfS.find_last_of(L"\\/");
    std::wstring name = (bs == std::wstring::npos) ? selfS : selfS.substr(bs + 1);
    if (name.empty()) name = L"ZZ_EDR.exe";

    // (1) IFEO 镜像劫持: 被指向调试器时本程序根本起不来
    {
        std::wstring sub = std::wstring(
            L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Image File Execution Options\\") + name;
        HKEY hk = nullptr;
        if (RegOpenKeyExW(HKEY_LOCAL_MACHINE, sub.c_str(), 0,
                          KEY_READ | KEY_SET_VALUE, &hk) == ERROR_SUCCESS && hk) {
            wchar_t dbg[MAX_PATH]; dbg[0] = 0; DWORD sz = sizeof(dbg), ty = 0;
            if (RegQueryValueExW(hk, L"Debugger", nullptr, &ty, (LPBYTE)dbg, &sz) == ERROR_SUCCESS && dbg[0]) {
                if (RegDeleteValueW(hk, L"Debugger") == ERROR_SUCCESS) {
                    ++fixed;
                    LogPost(L"[自修复] 已清除本程序的 IFEO 镜像劫持: " + std::wstring(dbg));
                }
            }
            RegCloseKey(hk);
        }
    }
    // (2) 软件限制策略(SRP) 默认级别 = 不允许 → 所有 EXE/C 程序均被禁
    {
        HKEY hk = nullptr;
        const wchar_t* sub = L"Software\\Policies\\Microsoft\\Windows\\Safer\\CodeIdentifiers";
        if (RegOpenKeyExW(HKEY_LOCAL_MACHINE, sub, 0, KEY_READ | KEY_SET_VALUE, &hk) == ERROR_SUCCESS && hk) {
            DWORD lv = 0, sz = sizeof(lv), ty = 0;
            if (RegQueryValueExW(hk, L"DefaultLevel", nullptr, &ty, (LPBYTE)&lv, &sz) == ERROR_SUCCESS) {
                if (lv == 0x00010000) {              // Disallowed
                    DWORD nv = 0x00040000;           // Unrestricted
                    if (RegSetValueExW(hk, L"DefaultLevel", 0, REG_DWORD,
                                       (const BYTE*)&nv, sizeof(nv)) == ERROR_SUCCESS) {
                        ++fixed;
                        LogPost(L"[自修复] 软件限制策略: 默认级别 不允许 -> 不受限 (恢复 EXE/C 运行)");
                    }
                }
            }
            RegCloseKey(hk);
        }
    }
    // (3) Explorer 策略 DisallowRun (HKCU / HKLM)
    {
        const wchar_t* sub = L"Software\\Microsoft\\Windows\\CurrentVersion\\Policies\\Explorer\\DisallowRun";
        HKEY roots[2] = { HKEY_CURRENT_USER, HKEY_LOCAL_MACHINE };
        for (int i = 0; i < 2; ++i) {
            HKEY hk = nullptr;
            if (RegOpenKeyExW(roots[i], sub, 0, KEY_READ, &hk) == ERROR_SUCCESS && hk) {
                RegCloseKey(hk);
                if (RegDeleteKeyW(roots[i], sub) == ERROR_SUCCESS) {
                    ++fixed;
                    LogPost(L"[自修复] 已清除 DisallowRun 策略 (恢复被禁程序)");
                }
            }
        }
    }
    // (4) AppLocker EXE 拒绝规则
    {
        HKEY hk = nullptr;
        const wchar_t* sub = L"SOFTWARE\\Policies\\Microsoft\\Windows\\SrpV2\\Exe";
        if (RegOpenKeyExW(HKEY_LOCAL_MACHINE, sub, 0, KEY_READ, &hk) == ERROR_SUCCESS && hk) {
            RegCloseKey(hk);
            if (RegDeleteKeyW(HKEY_LOCAL_MACHINE, sub) == ERROR_SUCCESS) {
                ++fixed;
                LogPost(L"[自修复] 已清除 AppLocker EXE 拒绝规则");
            }
        }
    }
    if (fixed) {
        // 【不能再调 gpupdate /force】HKLM\Software\Policies 只是「策略结果」,
        //   gpupdate 会重新应用 GPO, 把上面刚改好的 DefaultLevel 又刷回 Disallowed。
        //   (这是 v14.1.0 修掉的真 bug: 改完又刷回去, 等于白改)
        //   正确做法: 移走策略源文件 Registry.pol, 让封锁无法被重新应用。
        int pol = GpoPolicyPolClear();
        LogPost(L"[自修复] 共修复 " + std::to_wstring(fixed) + L" 项启动限制, 移走 " +
                std::to_wstring(pol) + L" 个策略源文件。");
        LogPost(L"[自修复] 未执行 gpupdate /force(会覆盖修复结果); 部分项需重启后完全生效。");
    }
    return fixed;
}

// 启动失败标记: 上次未能成功进入主界面 → 本次强制自修复
static std::wstring BootFailPath() {
    wchar_t tp[MAX_PATH]; tp[0] = 0;
    GetTempPathW(MAX_PATH, tp);
    return std::wstring(tp) + L"zz_EDR.bootfail";
}

